export const principles = [
  {id:'mentalism',name:'Mentalism',symbol:'01',control:'Shift the frame',idea:'The book treats mind as fundamental. Here, we explore the more modest question of how attention shapes a reading.',urban:'A wall can be read as a boundary, a canvas or a record. Its material stays the same while your frame changes.',reflection:'Describe one street twice: once as a stranger, once as someone who belongs there.',rap:'Four bars. Same street, two narrators. Let the last line change the first.',related:'Perception · narrative · point of view'},
  {id:'correspondence',name:'Correspondence',symbol:'02',control:'Change the scale',idea:'The book proposes correspondences between different planes. Analogy can generate a question; resemblance alone does not prove a shared mechanism.',urban:'A rose window and a street network both organize lines around centres. Compare their structures without claiming a secret common origin.',reflection:'Find one pattern at two scales. What changes when its function changes?',rap:'Make your first two bars a close-up and your next two a view from a rooftop.',related:'Analogy · scale · architectural geometry'},
  {id:'vibration',name:'Vibration',symbol:'03',control:'Adjust the wave spacing',idea:'The book describes reality through metaphysical vibration. This drawing changes a visual frequency; it does not measure a person or their consciousness.',urban:'A train, footsteps and a looped sample create different rhythms of repetition. Listen to their real differences.',reflection:'Listen for thirty seconds. Which sound repeats, and which interrupts?',rap:'Use the same words with three different rhythmic placements. Hear what the spacing does.',related:'Repetition · sound · pattern'},
  {id:'polarity',name:'Polarity',symbol:'04',control:'Move between light and shadow',idea:'The book describes opposites as degrees of a shared quality. This works as a contrast exercise, without making every difference equivalent.',urban:'A doorway moves gradually from sun to shade. Notice the middle tones instead of describing only two extremes.',reflection:'Choose a creative decision you have reduced to two options. Sketch an intermediate possibility.',rap:'Begin with a contradiction. Resolve it through a concrete image, not a slogan.',related:'Contrast · continuum · ambiguity'},
  {id:'rhythm',name:'Rhythm',symbol:'05',control:'Position the pendulum',idea:'The book emphasizes recurring motion. A regular pendulum is a model of a cycle, not a prediction of your life or of history.',urban:'Station arrivals, work shifts and an evening crowd have different temporal patterns. Observe before naming a cycle.',reflection:'Record one repeated sound. What evidence would you need to know whether it is regular?',rap:'Leave a deliberate silence after every fourth phrase. Make the pause part of the flow.',related:'Cycles · time · breath'},
  {id:'cause-effect',name:'Cause & Effect',symbol:'06',control:'Add an input to the chain',idea:'The book presents events as linked causes and effects. Sequence alone does not establish causation, and a result may have many inputs.',urban:'A venue changes a street through its program, opening times and neighbours. A single cause cannot explain the whole scene.',reflection:'Choose a change in your neighbourhood. Name two possible causes and one way to check them.',rap:'Build a four-line chain of events. On the last line, reveal an overlooked influence.',related:'Evidence · systems · multiple causes'},
  {id:'gender',name:'Gender',symbol:'07',control:'Combine the forms',idea:'“Gender” is the book’s historical metaphysical term. Our contemporary creative reading pairs receiving ideas with shaping them; both activities are open to everyone.',urban:'An artist receives a city through observation, then gives it a new form. Neither activity belongs to a sex or identity.',reflection:'Collect three visual details. Combine them into one mark that did not exist before.',rap:'Borrow an image from what you see, then answer it with an image of your own.',related:'Creation · receptivity · composition'}
];

export function contextualConnections(ids) {
  return principles.filter(p => Array.isArray(ids) && ids.includes(p.id)).map(p => ({ id:p.id, text:p.related }));
}
export function cleanJournal(value) { return typeof value === 'string' ? value.slice(0,4000) : ''; }

export function principleDrawing(index, value = 50) {
  const v = Math.max(0,Math.min(100,Number(value)||0));
  const circle = (x,y,r,extra='') => `<circle cx="${x}" cy="${y}" r="${r}" ${extra}/>`;
  const line = (x1,y1,x2,y2,extra='') => `<path d="M${x1} ${y1}L${x2} ${y2}" ${extra}/>`;
  const ring = circle(160,160,125,'opacity=".24"')+circle(160,160,105,'stroke-dasharray="2 8" opacity=".4"');
  let art='';
  if(index===0) art=`<g transform="rotate(${v*.9} 160 160)"><rect x="105" y="105" width="110" height="110"/>${line(70,160,250,160)}${line(160,70,160,250)}</g>${circle(160,160,14,'fill="currentColor"')}`;
  if(index===1) art=[0,1,2,3].map(n=>`<g transform="rotate(${45+n*v*.22} 160 160)"><rect x="${67+n*20}" y="${67+n*20}" width="${186-n*40}" height="${186-n*40}" opacity="${1-n*.15}"/></g>`).join('');
  if(index===2) { const pts=Array.from({length:121},(_,n)=>`${40+n*2},${160+Math.sin(n/120*Math.PI*(2+v/8))*55}`).join(' ');art=`<polyline points="${pts}"/>${line(40,160,280,160,'opacity=".25"')}`; }
  if(index===3) art=`${circle(160,160,76,`fill="hsl(40 15% ${10+v*.72}%)"`)}<path d="M160 84a76 76 0 010 152a38 38 0 000-76a38 38 0 010-76" fill="currentColor"/>${circle(160,122,6,'fill="#080808"')}${circle(160,198,6,'fill="currentColor"')}`;
  if(index===4) {const a=(v-50)*.018;const x=160+Math.sin(a)*100,y=85+Math.cos(a)*100;art=line(160,85,x,y)+circle(x,y,19,'fill="currentColor"')+`<path d="M80 175Q160 240 240 175" stroke-dasharray="3 5" opacity=".4"/>`+circle(160,85,4,'fill="currentColor"');}
  if(index===5) art=[0,1,2,3].map(n=>circle(64+n*64,160,15,n<=Math.floor(v/26)?'fill="currentColor"':'opacity=".3"')).join('')+line(80,160,240,160,'opacity=".6"')+line(160,90,192,145,'stroke-dasharray="3 4"')+circle(160,80,10,'opacity=".5"');
  if(index===6) art=`${circle(110+v*.35,160,57)}${circle(210-v*.35,160,57)}<path d="M160 70L235 200H85Z" opacity=".4"/>`;
  return `<svg viewBox="0 0 320 320" role="img" aria-label="Interactive ${principles[index].name} illustration"><g fill="none" stroke="currentColor" stroke-width="1.3">${ring}${art}</g></svg>`;
}
